{
  "findings": [
    {
      "check_id": "CKV_AZURE_25",
      "title": "SQL threat detection alert types are disabled",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "HIGH",
      "explanation": "The policy explicitly disables SQL injection and data exfiltration alerts, preventing detection of two high-impact attack categories."
    },
    {
      "check_id": "CKV_AZURE_27",
      "title": "SQL security alerts are not sent to account administrators",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "MEDIUM",
      "explanation": "The policy does not enable notifications for account administrators, relying solely on one explicitly configured email address that may become unavailable or outdated."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Insufficient SQL security alert retention",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "MEDIUM",
      "explanation": "Security alert data is retained for only 20 days, limiting historical investigation and detection of incidents discovered after that period."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server_security_alert_policy\" \"alertpolicy6\" {\n  resource_group_name        = azurerm_resource_group.example.name\n  server_name                = azurerm_mssql_server.mssql6.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.security_storage_account.primary_blob_endpoint\n  storage_account_access_key = azurerm_storage_account.security_storage_account.primary_access_key\n  disabled_alerts            = []\n  retention_days             = 90\n  email_account_admins       = true\n  email_addresses            = [\"securityengineer@bridgecrew.io\"]\n}\n",
  "fix_summary": "Enabled all SQL threat detection alert categories, configured alerts to reach account administrators, and increased security alert retention from 20 to 90 days."
}
